def transform(grid):
 g=[r[:] for r in grid]; H=len(g);W=len(g[0])
 seen=set(); comps=[]
 for r in range(H):
  for c in range(W):
   if g[r][c]!=8 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c)); cells=[]
    while q:
     y,x=q.pop();cells.append((y,x))
     for dy in (-1,0,1):
      for dx in (-1,0,1):
       if not (dy or dx):continue
       yy,xx=y+dy,x+dx
       if 0<=yy<H and 0<=xx<W and g[yy][xx]!=8 and (yy,xx) not in seen:
        seen.add((yy,xx));q.append((yy,xx))
    comps.append(cells)
 for cells in comps:
  rs=[p[0] for p in cells];cs=[p[1] for p in cells]; r0,r1=min(rs),max(rs);c0,c1=min(cs),max(cs)
  colors=[g[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1) if g[r][c] not in (3,8)]
  if not colors:continue
  color=colors[0]
  for r in range(r0,r1+1):
   for c in range(c0,c1+1):
    if (r not in (r0,r1) and c not in (c0,c1)) or g[r][c]!=8:continue
    dr=-1 if r==r0 else 1 if r==r1 else 0
    dc=-1 if c==c0 else 1 if c==c1 else 0
    y,x=r+dr,c+dc
    while 0<=y<H and 0<=x<W:
     g[y][x]=color;y+=dr;x+=dc
 return g
